:scope .pm-chapter-section {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #003366;
  --warm: #cc0066;
  --line: #ddd;
  --paper: #f5f5f5;
  --highlight: #e6f0ff;
  --closest: #ffe6f0;

  font-family: system-ui, -apple-system, sans-serif;
  background-color: var(--paper);
  color: var(--ink);
  padding: 2rem 1rem;
  line-height: 1.6;
  box-sizing: border-box;
}

:scope .pm-section-header {
  margin-bottom: 2rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 1rem;
}

:scope .pm-section-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  margin: 0 0 0.5rem 0;
  font-family: Georgia, serif;
}

:scope .pm-section-lead {
  font-size: 1rem;
  color: var(--muted);
  margin: 0;
  max-width: 60ch;
}

:scope .pm-data-workbench {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  :scope .pm-data-workbench {
    grid-template-columns: 1.5fr 1fr;
  }
}

:scope .pm-table-container {
  overflow-x: auto;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 1rem;
}

:scope .pm-evidence-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
  min-width: 600px;
}

:scope .pm-evidence-table th,
:scope .pm-evidence-table td {
  text-align: left;
  padding: 0.75rem;
  border-bottom: 1px solid var(--line);
}

:scope .pm-evidence-table th {
  font-weight: 600;
  color: var(--accent);
  background: #fafafa;
}

:scope .pm-evidence-table tbody tr {
  cursor: pointer;
  transition: background-color 0.2s ease;
}

:scope .pm-evidence-table tbody tr:hover {
  background-color: var(--highlight);
}

:scope .pm-evidence-table tbody tr.selected {
  background-color: var(--highlight);
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

:scope .pm-evidence-table td.closest-cell {
  background-color: var(--closest);
  font-weight: 700;
  color: var(--warm);
  position: relative;
}

:scope .pm-evidence-table td.closest-cell::after {
  content: '★';
  position: absolute;
  top: 2px;
  right: 4px;
  font-size: 0.8rem;
  color: var(--warm);
}

:scope .pm-table-note {
  font-size: 0.8rem;
  color: var(--muted);
  margin-top: 0.5rem;
  font-style: italic;
}

:scope .pm-analysis-panel {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
}

:scope .pm-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.5rem;
}

:scope .pm-panel-header h3 {
  margin: 0;
  font-size: 1.1rem;
  color: var(--ink);
}

:scope .pm-source-buttons {
  display: flex;
  gap: 0.5rem;
}

:scope .pm-btn-source {
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
  padding: 0.25rem 0.75rem;
  font-size: 0.8rem;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}

:scope .pm-btn-source:hover {
  background: var(--accent);
  color: #fff;
}

:scope .pm-metric-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

:scope .pm-metric-item {
  background: #fafafa;
  padding: 1rem;
  border-radius: 4px;
  border-left: 3px solid var(--accent);
}

:scope .pm-metric-label {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  margin-bottom: 0.25rem;
}

:scope .pm-metric-value {
  display: block;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--ink);
}

:scope .pm-detail-explanation {
  font-size: 0.95rem;
  color: var(--ink);
  margin-bottom: 1rem;
}

:scope .pm-limitation-alert {
  background: #fff0f5;
  border: 1px solid var(--warm);
  color: var(--warm);
  padding: 1rem;
  border-radius: 4px;
  font-size: 0.9rem;
}

:scope .pm-limitation-alert p {
  margin: 0;
}

@media (prefers-reduced-motion: reduce) {
  :scope .pm-evidence-table tbody tr {
    transition: none;
  }
  :scope .pm-btn-source {
    transition: none;
  }
}
