(function() {
  'use strict';

  // Data Access
  const tables = window.paperMindData && window.paperMindData.tables ? window.paperMindData.tables : [];
  const tableData = tables.find(t => t.id === 'p4-table-1');

  const section = document.getElementById('bias-validation-results');
  const tableBody = section ? section.querySelector('#bias-validation-table tbody') : null;
  const explanationEl = section ? section.querySelector('#detail-explanation') : null;
  const signConsistencyEl = section ? section.querySelector('#metric-sign-consistency') : null;
  const closestModelEl = section ? section.querySelector('#metric-closest-model') : null;
  const limitationAlertEl = section ? section.querySelector('#limitation-alert') : null;
  const sourceButtons = section ? section.querySelectorAll('.pm-btn-source') : [];

  if (!tableData || !tableBody) {
    if (explanationEl) explanationEl.innerHTML = '<p>数据加载失败：无法找到 Table 1 数据。</p>';
    return;
  }

  // Render Table
  const rows = tableData.rows || [];
  rows.forEach((row, index) => {
    const tr = document.createElement('tr');
    tr.dataset.rowIndex = index;
    tr.dataset.testNo = row.values['Test no.'];

    // Create cells
    const cols = ['Test no.', 'Target Words', 'Attribute Words', 'w2v', 'FT', 'CA', 'IAT'];
    cols.forEach(col => {
      const td = document.createElement('td');
      td.textContent = row.values[col];
      td.dataset.col = col;
      tr.appendChild(td);
    });

    tableBody.appendChild(tr);
  });

  // Interaction Logic
  const handleRowClick = (e) => {
    const tr = e.currentTarget;
    const rowIndex = tr.dataset.rowIndex;
    const rowData = rows[rowIndex];
    const testNo = rowData.values['Test no.'];

    // Highlight Row
    const allRows = tableBody.querySelectorAll('tr');
    allRows.forEach(r => r.classList.remove('selected'));
    tr.classList.add('selected');

    // Clear previous cell highlights
    const allCells = tableBody.querySelectorAll('td');
    allCells.forEach(c => c.classList.remove('closest-cell'));

    // Parse Values
    const w2v = Number(rowData.values['w2v']);
    const ft = Number(rowData.values['FT']);
    const ca = Number(rowData.values['CA']);
    const iat = Number(rowData.values['IAT']);

    // Check Sign Consistency (All Positive)
    const signs = [w2v, ft, ca, iat].map(v => v > 0 ? '正' : (v < 0 ? '负' : '零'));
    const isConsistent = signs.every(s => s === '正');

    if (signConsistencyEl) {
      signConsistencyEl.textContent = isConsistent ? '完全一致 (均为正)' : '存在差异';
      signConsistencyEl.style.color = isConsistent ? 'var(--accent)' : 'var(--warm)';
    }

    // Calculate Distance to IAT
    const distW2v = Math.abs(w2v - iat);
    const distFt = Math.abs(ft - iat);
    const distCa = Math.abs(ca - iat);

    let closestModel = 'w2v';
    let minDist = distW2v;
    let closestCellSelector = `tr[data-row-index="${rowIndex}"] td[data-col="w2v"]`;

    if (distFt < minDist) {
      closestModel = 'FT';
      minDist = distFt;
      closestCellSelector = `tr[data-row-index="${rowIndex}"] td[data-col="FT"]`;
    }
    if (distCa < minDist) {
      closestModel = 'CA';
      minDist = distCa;
      closestCellSelector = `tr[data-row-index="${rowIndex}"] td[data-col="CA"]`;
    }

    // Highlight Closest Cell
    const closestCell = section.querySelector(closestCellSelector);
    if (closestCell) closestCell.classList.add('closest-cell');

    if (closestModelEl) {
      closestModelEl.textContent = closestModel;
      closestModelEl.style.color = closestModel === 'FT' ? 'var(--accent)' : 'var(--muted)';
    }

    // Update Explanation
    if (explanationEl) {
      const target = rowData.values['Target Words'];
      const attr = rowData.values['Attribute Words'];
      explanationEl.innerHTML = `
        <p><strong>测试 ${testNo}：</strong> ${target} vs ${attr}。</p>
        <p>人类基准 (IAT) 效应值为 ${iat}。在此测试中，${closestModel} 模型的结果 (${rowData.values[closestModel]}) 最接近人类实测值，差距为 ${minDist.toFixed(2)}。</p>
        <p>所有模型均检测到正向偏见关联。</p>
      `;
    }

    // Show Limitation Alert for Tests 3, 6, 8
    if (limitationAlertEl) {
      if (['3', '6', '8'].includes(testNo)) {
        limitationAlertEl.style.display = 'block';
      } else {
        limitationAlertEl.style.display = 'none';
      }
    }
  };

  // Attach Event Listeners
  const tableRows = tableBody.querySelectorAll('tr');
  tableRows.forEach(row => {
    row.addEventListener('click', handleRowClick);
  });

  // Source Buttons (Host handles logic, just ensure attributes exist)
  sourceButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      // No action needed here, host kernel handles data-source attribute
    });
  });

  // Initialize with first row selected for default view
  if (tableRows.length > 0) {
    tableRows[0].click();
  }
})();
